import{_ as l,o as t,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2019-01-08","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2019-01-08","date":"2019-01-08T00:00:00.000Z","updated":"2019-01-10T00:00:00.000Z","tags":["Ceph","Crimson OSD","Seastar","Distributed Storage","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.md","filePath":"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.md","lastUpdated":1780460162000}'),o={name:"posts/2019/Crimson_Seastar_OSD_Meeting_2019-01-08.md"};function n(e,i,a,g,u,S){return t(),r("div",null,[...i[0]||(i[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年1月8日</p><p><strong>参会人员</strong>： 多位Ceph研发人员，特别是负责Crimson OSD和Seastar项目的人员</p><p><strong>会议主题</strong>： 讨论Crimson OSD项目的进展，包括内存存储、对象存储、性能测试等议题</p><p><strong>关键细节</strong>：</p><ul><li><strong>Crimson OSD项目</strong>： <ul><li>目标是提高Ceph的性能，特别是针对快速设备的使用。</li><li>目前重点关注1:1映射模式，并考虑未来可能转向M:N映射模式。</li><li>内存存储是Crimson OSD项目的一个重要组成部分，将用于测试性能提升。</li></ul></li><li><strong>内存存储</strong>： <ul><li>正在开发内存存储，并计划使用Sister框架。</li><li>内存存储将继承自现有的对象存储接口，并实现新的方法。</li><li>内存存储将使用原子操作来避免锁的使用，以提高性能。</li></ul></li><li><strong>对象存储</strong>： <ul><li>正在开发新的对象存储接口，以支持内存存储和磁盘存储。</li><li>新接口将使用Sister框架，并返回Sister future。</li><li>需要开发适配器，将现有对象存储与新的接口进行兼容。</li></ul></li><li><strong>性能测试</strong>： <ul><li>将使用性能测试来评估Crimson OSD项目的性能。</li><li>将使用单线程和并发测试来评估性能。</li><li>将使用与现有OSD相同的硬件和配置进行测试。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>1:1映射与M:N映射</strong>： <ul><li>团队一致认为，目前应专注于1:1映射模式，并考虑未来可能转向M:N映射模式。</li><li>1:1映射模式更简单，更容易实现，并且可以更快地验证性能提升。</li></ul></li><li><strong>内存存储</strong>： <ul><li>团队讨论了内存存储的设计和实现。</li><li>团队决定使用Sister框架，并使用原子操作来避免锁的使用。</li></ul></li><li><strong>对象存储</strong>： <ul><li>团队讨论了新的对象存储接口的设计和实现。</li><li>团队决定使用Sister框架，并返回Sister future。</li></ul></li><li><strong>性能测试</strong>： <ul><li>团队讨论了性能测试的计划和方法。</li><li>团队决定使用单线程和并发测试来评估性能。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li><strong>Crimson OSD项目</strong>： <ul><li>焦点放在1:1映射模式上。</li><li>开发内存存储和新的对象存储接口。</li><li>进行性能测试。</li></ul></li><li><strong>内存存储</strong>： <ul><li>使用Sister框架。</li><li>使用原子操作来避免锁的使用。</li></ul></li><li><strong>对象存储</strong>： <ul><li>使用Sister框架。</li><li>返回Sister future。</li></ul></li><li><strong>性能测试</strong>： <ul><li>使用单线程和并发测试来评估性能。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>开发内存存储和新的对象存储接口。</li><li>进行性能测试。</li><li>完成Crimson OSD项目的其他工作。</li></ul><p><strong>关键词</strong>：</p><ul><li>Crimson OSD</li><li>内存存储</li><li>对象存储</li><li>Sister框架</li><li>1:1映射</li><li>M:N映射</li><li>性能测试</li><li>原子操作</li><li>锁</li><li>调度器</li></ul>',14)])])}const m=l(o,[["render",n]]);export{_ as __pageData,m as default};
